INSERT INTO npc_text (ID, text0_0, text0_1, prob0) VALUES (990102, 'Ce raid se fait à 10 ou à 20 joueurs : les ennemis sont ajustés à la taille choisie, et le butin aussi (boss : 2 objets à 10, 3 à 20 ; boss final et boss légendaire : 3 à 10, 4 à 20).$B$BTrente secondes après la chute du boss final, un boss légendaire surgit. Il donne à chacun un fragment, une seule fois par personnage.$B$BLe chef de groupe choisit la taille avant le premier combat ; par défaut, le raid est à 20 joueurs.', 'Ce raid se fait à 10 ou à 20 joueurs : les ennemis sont ajustés à la taille choisie, et le butin aussi (boss : 2 objets à 10, 3 à 20 ; boss final et boss légendaire : 3 à 10, 4 à 20).$B$BTrente secondes après la chute du boss final, un boss légendaire surgit. Il donne à chacun un fragment, une seule fois par personnage.$B$BLe chef de groupe choisit la taille avant le premier combat ; par défaut, le raid est à 20 joueurs.', 1);
