-- Raids à 10 ou 20 joueurs, boss légendaires, fragments (généré)
SET NAMES utf8mb4;
DELETE FROM creature WHERE id BETWEEN 990150 AND 990159;
DELETE FROM creature_template WHERE Entry BETWEEN 990150 AND 990159 OR Entry BETWEEN 990450 AND 990459;
DELETE FROM creature_spell_list WHERE Id BETWEEN 990450 AND 990459;
DELETE FROM creature_spell_list_entry WHERE Id BETWEEN 990450 AND 990459;
DELETE FROM creature_loot_template WHERE entry BETWEEN 998000 AND 998999;
DELETE FROM reference_loot_template WHERE entry BETWEEN 998000 AND 998999;
DELETE FROM item_template WHERE entry BETWEEN 999000 AND 999009;
DELETE FROM gossip_menu WHERE entry=60102;
DELETE FROM npc_text WHERE ID=990102;
CREATE TABLE IF NOT EXISTS custom_raid_boss (entry INT UNSIGNED NOT NULL PRIMARY KEY, raid INT NOT NULL, loot10 INT UNSIGNED NOT NULL, loot20 INT UNSIGNED NOT NULL, final TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
DELETE FROM custom_raid_boss;

